    "표2_역사적배경": [
        {"항목":"네 바람의 상징", "내용":"고대 근동에서 사방의 바람은 온 세계를 의미했다. 하늘의 네 바람이 큰 바다를 격동시키는 것은 하나님의 통치가 온 세계에 미침을 나타낸다.", "목회적활용":"하나님의 주권은 전 세계적이며, 어떤 지역이나 상황도 그분의 통제 밖에 있지 않음을 선포한다"},
        {"항목":"큰 바다의 의미", "내용":"'큰 바다'(지중해)는 고대 이스라엘에서 열방과 세상을 상징했다. 다니엘 7장에서 바다는 혼돈과 인간 제국의 기원을 나타낸다.", "목회적활용":"세상의 혼란과 강대국들의 부침도 하나님의 계획 안에 있음을 가르친다"},
        {"항목":"밤 이상의 의미", "내용":"밤은 어둠과 불확실성을 상징하지만, 그 안에서 하나님의 계시가 임한다. 이는 어두운 시대에도 빛이 되시는 하나님을 보여준다.", "목회적활용":"삶의 어두운 시기에도 하나님은 임재하시며 인도하심을 선포한다"}
    ],
    "표3_신학적의미": [
        {"교리":"하나님의 주권", "설명":"하늘의 바람을 움직이시는 하나님은 세상의 모든 격동을 통제하신다. 인간의 역사는 그분의 계획 안에서 전개된다.", "관련구절":"시 135:7, 렘 49:36, 겔 37:9, 요 3:8"},
        {"교리":"묵시적 우주론", "설명":"바다와 바람의 상징은 하나님과 혼돈의 대립을 나타내며, 궁극적으로 하나님의 통치가 모든 혼돈을 정복함을 선언한다.", "관련구절":"창 1:2, 욥 26:12, 시 89:9, 계 21:1"},
        {"교리":"예언과 성취", "설명":"네 바람에서 나오는 네 짐승은 역사에 실제로 나타난 제국들로 성취되었다. 이는 하나님의 예언의 정확성을 증거한다.", "관련구절":"사 46:10, 단 2:38-40, 마 24:35, 계 17:9-11"}
    ],
    "표4_예표론": [
        {"구분":"큰 바다", "내용":"혼돈의 바다에서 짐승들이 나오는 것은 죄의 세상에서 악한 세력이 일어남을 예표한다", "그리스도연결":"그리스도께서 바다 위를 걸으시며 파도를 잔잔케 하신 것은 혼돈을 정복하시는 주권을 보여줌(마 8:26)"},
        {"구분":"하늘의 네 바람", "내용":"하나님이 바람을 움직이시는 것은 성령의 역사를 예표한다", "그리스도연결":"오순절에 성령이 급하고 강한 바람 같이 임하심(행 2:2)"},
        {"구분":"밤의 이상", "내용":"어둠 속의 계시는 율법 아래 어둠 속에 있던 인류에게 임한 복음의 빛을 예표한다", "그리스도연결":"빛이 세상에 오신 그리스도(요 1:9)"}
    ],
    "표5_매튜헨리": [
        {"영어원문":"The four winds of heaven strove upon the great sea, denoting the agitation and commotion of the nations of the earth.", "한국어번역":"하늘의 네 바람이 큰 바다를 격동시켰으니, 이는 세상 열방의 동요와 혼란을 나타낸다.", "핵심통찰":"세상의 혼란은 하나님의 계획 안에서 이루어지는 역사적 과정이다"},
        {"영어원문":"The sea represents the nations of the world in a state of turbulence, out of which the great empires arose.", "한국어번역":"바다는 혼란한 상태의 세상 열방을 나타내며, 그로부터 위대한 제국들이 일어났다.", "핵심통찰":"인간 제국의 흥망은 하나님의 허용과 주권 아래 있다"},
        {"영어원문":"God controls the winds that stir the sea of nations, showing that history is in His hands.", "한국어번역":"하나님은 열방의 바다를 격동시키는 바람을 통제하시며, 역사가 그분의 손 안에 있음을 보여주신다.", "핵심통찰":"역사의 모든 사건 배후에 하나님의 주권적 통치가 있다"}
    ],
    "표6_설교자료": [
        {"대지":"제목", "내용":"혼돈을 다스리시는 하나님: 바람과 바다의 신학", "예화_적용":"역사의 폭풍 속에서도 하나님은 키를 잡고 계신다"},
        {"대지":"서론", "내용":"세상은 끊임없이 격동한다. 전쟁, 혁명, 팬데믹... 그러나 다니엘의 환상은 이 모든 격동 뒤에 하나님의 손이 있음을 보여준다.", "예화_적용":"최근 세계의 격동하는 사건들을 언급하며 청중의 관심을 끈다"},
        {"대지":"1대지", "내용":"하나님은 역사의 바람을 움직이신다 (하늘의 네 바람)", "예화_적용":"나침반의 사방이 하나님의 통치 아래 있듯이, 세상의 모든 방향도 그분의 손 안에 있다"},
        {"대지":"2대지", "내용":"세상의 혼돈도 하나님의 계획 안에 있다 (큰 바다가 격동함)", "예화_적용":"항해사는 폭풍을 만나도 목적지를 안다. 하나님은 역사의 폭풍 속에서도 목적지를 아신다"},
        {"대지":"3대지", "내용":"하나님의 계시는 어두운 밤에도 임한다 (밤에 이상을 봄)", "예화_적용":"가장 어두운 밤에 별이 가장 밝게 빛난다. 시련 중에 하나님의 음성이 더 선명하다"},
        {"대지":"결론", "내용":"세상이 격동할수록 우리는 하나님의 주권을 더욱 굳게 신뢰해야 한다. 바람을 움직이시는 그분이 우리의 삶도 인도하신다.", "예화_적용":"오늘 당신의 삶에서 격동하는 바다는 무엇인가? 그것도 하나님의 손 안에 있다"}
    ],
